$evidences=find_by_sql("SELECT e.*,u.name subido_por_nombre FROM activos_mantenimiento_hallazgo_evidencias e LEFT JOIN users u ON u.id=e.subido_por WHERE e.hallazgo_id={$id} ORDER BY e.id DESC");
