$users=find_by_sql("SELECT id,name FROM users WHERE status=1 ORDER BY name");
$correctives=find_by_sql("SELECT id,folio,estado,fecha_programada FROM activos_mantenimientos WHERE IdMaquina=".(int)$h['IdMaquina']." AND id<>".(int)$h['mantenimiento_id']." ORDER BY id DESC LIMIT 100");
