ar_hallazgo.php" class="mt-2 mt-md-0"><?=csrf_input()?><input type="hidden" name="hallazgo_id" value="<?=$id?>"><input type="hidden" name="estado" value="PENDIENTE_VERIFICACION"><button class="btn btn-info font-weight-bold">Continuar a verificaci&oacute;n <i class="fas fa-arrow-right ml-1"></i></button></form></div></div><?php endif;?>
